local config = {
  str_homestory_N24diaoyu_90050101_1_dialog_content = "Vice!",
  str_homestory_N24diaoyu_90050101_2_dialog_content = "Hi, PlayerName.",
  str_homestory_N24diaoyu_90050101_3_dialog_content = "Are you still into catching bugs or collecting seashells to add to your specimen collection?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050101_4_dialog_content = "I haven't been doing that for a while now.",
  str_homestory_N24diaoyu_90050101_5_dialog_content = "Sure, there are many different plants and animals in Cloud Gardens, but it still gets old after doing it everyday from day to night.",
  str_homestory_N24diaoyu_90050101_6_dialog_content = "Oh, everyday from day to night? You sure have been one with nature, haven't you, PlayerName?",
  str_homestory_N24diaoyu_90050101_7_dialog_content = "What do you plan to do next?",
  str_homestory_N24diaoyu_90050101_8_dialog_content = "How about a museum that exhibits all the plants and animals in Cloud Gardens for all visiting Aurorians to see?",
  str_homestory_N24diaoyu_90050101_9_dialog_content = "<sprite=emo_dianzan size=60 />That's a great idea! Let me think...",
  str_homestory_N24diaoyu_90050101_10_dialog_content = "But it's gonna cost a lot of money.<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050101_11_dialog_content = "Of course. A museum needs a lot of equipment to protect its collections.",
  str_homestory_N24diaoyu_90050101_12_dialog_content = "Like temperature, humidity control systems and...",
  str_homestory_N24diaoyu_90050101_13_dialog_content = "Wait. Was that Barton just now?",
  str_homestory_N24diaoyu_90050101_14_dialog_content = "Huh? Someone went by us? I wasn't paying attention.",
  str_homestory_N24diaoyu_90050101_15_dialog_content = "Never mind. I probably just saw something in the corner of my eye that wasn't there.",
  str_homestory_N24diaoyu_90050101_16_dialog_content = "<sprite=emo_laba size=60 />PlayerName! PlayerName!",
  str_homestory_N24diaoyu_90050101_17_dialog_content = "Fia?",
  str_homestory_N24diaoyu_90050101_18_dialog_content = "Come help, PlayerName! I need you to help me with a lot of things!",
  str_homestory_N24diaoyu_90050101_19_dialog_content = "What, you're not even gonna pretend you have a \"small\" favor to ask now?",
  str_homestory_N24diaoyu_90050101_20_dialog_content = "Just coming straight at me with all of your problems now...<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050101_21_dialog_content = "Um, I thought we were past beating around the bush, PlayerName!",
  str_homestory_N24diaoyu_90050101_22_dialog_content = "You're right. Then just let me turn you down right here, right now.",
  str_homestory_N24diaoyu_90050101_23_dialog_content = "Huh? Why!<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050101_24_dialog_content = "I'm occupied. I need to build a museum in Cloud Gardens.",
  str_homestory_N24diaoyu_90050101_25_dialog_content = "This is something huge for Cloud Gardens. I have no time to play around with you.",
  str_homestory_N24diaoyu_90050101_26_dialog_content = "Helping me is \"playing around\"!?",
  str_homestory_N24diaoyu_90050101_27_dialog_content = "<sprite=emo_shengqi size=60 />Okay PlayerName, I won't help you the next time, then! You're gonna regret this, you fool!",
  str_homestory_N24diaoyu_90050101_28_dialog_content = "She ran away. Is it really all right to leave Fia alone like this?",
  str_homestory_N24diaoyu_90050101_29_dialog_content = "I can't spoil her by doing everything for her.",
  str_homestory_N24diaoyu_90050101_30_dialog_content = "At one point or another, she'll need to learn to solve things on her own. I'll give her the extra push when she really needs it.",
  str_homestory_N24diaoyu_90050101_31_dialog_content = "This is how she grows.",
  str_homestory_N24diaoyu_90050101_32_dialog_content = "<sprite=emo_chidai size=60 />Whoa... You're really becoming a great mentor, PlayerName.",
  str_homestory_N24diaoyu_90050101_33_dialog_content = "It's either that, or that's just all talk on your part.",
  str_homestory_N24diaoyu_90050101_34_dialog_content = "Heheh...",
  str_homestory_N24diaoyu_90050101_35_dialog_content = "Huh? Did Fleur just run by?",
  str_homestory_N24diaoyu_90050101_36_dialog_content = "Barton, Fia, and now Fleur... Why are they all in a hurry?",
  str_homestory_N24diaoyu_90050101_37_dialog_content = "I can't stand this. I have to catch up with them and see what's going on.",
  str_homestory_N24diaoyu_90050102_1_dialog_content = "<sprite=emo_hanshui size=60 />Huff, puff!",
  str_homestory_N24diaoyu_90050102_2_dialog_content = "PlayerName, you better take a breather before you collapse.",
  str_homestory_N24diaoyu_90050102_3_dialog_content = "Vice? PlayerName? Why are you two panting like that?",
  str_homestory_N24diaoyu_90050102_4_dialog_content = "I... I'm trying to catch up to Fleur.",
  str_homestory_N24diaoyu_90050102_5_dialog_content = "And I'm trying to be a good friend to him.",
  str_homestory_N24diaoyu_90050102_6_dialog_content = "How... How can Fleur run so fast? He doesn't seem like the athletic type.",
  str_homestory_N24diaoyu_90050102_7_dialog_content = "Really? I actually see Fleur jogging around Cloud Gardens quite often.",
  str_homestory_N24diaoyu_90050102_8_dialog_content = "What? Is that who he really is? <sprite=emo_tanqi size=60 />Could've fooled me...",
  str_homestory_N24diaoyu_90050102_9_dialog_content = "So, why are you after Fleur, PlayerName?",
  str_homestory_N24diaoyu_90050102_10_dialog_content = "Or... are you just doing it for fun?",
  str_homestory_N24diaoyu_90050102_11_dialog_content = "For fun? No way!",
  str_homestory_N24diaoyu_90050102_12_dialog_content = "Well... It's not like there's anything important. I just want to know why he's in a hurry.",
  str_homestory_N24diaoyu_90050102_13_dialog_content = "That's the very definition of \"for fun,\" isn't it?<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050102_14_dialog_content = "Jokes aside, I think I know what Fleur is up to.",
  str_homestory_N24diaoyu_90050102_15_dialog_content = "Really? You do?",
  str_homestory_N24diaoyu_90050102_16_dialog_content = "Yeah. Judging by what he is wearing, he's probably going fishing.",
  str_homestory_N24diaoyu_90050102_17_dialog_content = "<sprite=emo_sikao size=60 />Fishing...?",
  str_homestory_N24diaoyu_90050102_18_dialog_content = "Yeah. I heard it's an event jointly hosted by a publisher and many guilds of Umbraton, suggested by a Rediesel Desert Aurorian.",
  str_homestory_N24diaoyu_90050102_19_dialog_content = "This \"<color=#FFB400>An Extraordinary Catch</color>\" fishing contest turns out to be quite a hit. The contestants are called <color=#FFB400>Anglers</color>.",
  str_homestory_N24diaoyu_90050102_20_dialog_content = "Fleur must've joined the contest and is trying to compete against other Anglers.",
  str_homestory_N24diaoyu_90050102_21_dialog_content = "The grand prize of this kind of event must be a souvenir or something... I just didn't expect Fleur to be interested in this.",
  str_homestory_N24diaoyu_90050102_22_dialog_content = "I don't think that's the case. The prize is said to be a <color=#FFB400>pure gold fishing rod covered with Lumamber</color>.",
  str_homestory_N24diaoyu_90050102_23_dialog_content = "Pure gold, you say...?",
  str_homestory_N24diaoyu_90050102_24_dialog_content = "And covered with Lumamber...",
  str_homestory_N24diaoyu_90050102_25_dialog_content = "<sprite=emo_mojing size=60 />Ahem! Carleen, you must know that people in Cloud Gardens call me the \"Dragonwave Angler.\"",
  str_homestory_N24diaoyu_90050102_26_dialog_content = "There's no way I'll let them take any fish away from me!",
  str_homestory_N24diaoyu_90050102_27_dialog_content = "(If I win, I'll have the funds to build a museum!<sprite=emo_baiyebi size=60 />)",
  str_homestory_N24diaoyu_90050102_28_dialog_content = "You want to join?",
  str_homestory_N24diaoyu_90050102_29_dialog_content = "If you do, you'll have to reach out to Bethel, who represents the guilds hosting this event...",
  str_homestory_N24diaoyu_90050102_30_dialog_content = "<sprite=emo_dianzan size=60 />Got it! Thanks, Carleen!",
  str_homestory_N24diaoyu_90050102_31_dialog_content = "I wasn't even done yet.",
  str_homestory_N24diaoyu_90050102_32_dialog_content = "Well... Why don't we join the contest with PlayerName?",
  str_homestory_N24diaoyu_90050102_33_dialog_content = "Huh?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_1_dialog_content = "Bethel!",
  str_homestory_N24diaoyu_90050103_2_dialog_content = "PlayerName, Vice. Oh, and Lady Carleen too!",
  str_homestory_N24diaoyu_90050103_3_dialog_content = "Long time no see. Did you finish the novel I recommended, Vice?",
  str_homestory_N24diaoyu_90050103_4_dialog_content = "Almost! I enjoy how it really delves into the emotions of the protagonist!",
  str_homestory_N24diaoyu_90050103_5_dialog_content = "And his relationship with Genie, his mechanical companion, is quite touching as well!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050103_6_dialog_content = "<sprite=emo_aixin size=60 />Right? Right? A relationship like that is so platonic...",
  str_homestory_N24diaoyu_90050103_7_dialog_content = "Ahem!",
  str_homestory_N24diaoyu_90050103_8_dialog_content = "Vice, we're not here to chat about the novel...",
  str_homestory_N24diaoyu_90050103_9_dialog_content = "We're actually here because we want to sign up for the fishing contest!",
  str_homestory_N24diaoyu_90050103_10_dialog_content = "Oh! I didn't know you were all interested in fishing!",
  str_homestory_N24diaoyu_90050103_11_dialog_content = "You kidding me? I am the renowned Dragonwave Angler of Cloud Gardens!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_12_dialog_content = "I am very interested in the grand prize!<sprite=emo_baiyebi size=60 />",
  str_homestory_N24diaoyu_90050103_13_dialog_content = "Well... I'm here because they are.",
  str_homestory_N24diaoyu_90050103_14_dialog_content = "I see. But, I'm sorry, I haven't heard anything about a Dragonwave Angler.",
  str_homestory_N24diaoyu_90050103_15_dialog_content = "Oh, the world shall know my name once I take home the grand prize!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050103_16_dialog_content = "Right... That would be something to look forward to. However...",
  str_homestory_N24diaoyu_90050103_17_dialog_content = "Hmm?",
  str_homestory_N24diaoyu_90050103_18_dialog_content = "The registration period has ended.",
  str_homestory_N24diaoyu_90050103_19_dialog_content = "<sprite=emo_xinsui size=60 />What!?",
  str_homestory_N24diaoyu_90050103_20_dialog_content = "PlayerName looks so disappointed. Is it such a huge blow to him, not being able to join the contest?",
  str_homestory_N24diaoyu_90050103_21_dialog_content = "Probably... I mean, he was even trying to come up with names for his casting.",
  str_homestory_N24diaoyu_90050103_22_dialog_content = "Well... There is a way.",
  str_homestory_N24diaoyu_90050103_23_dialog_content = "There is a way!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050103_24_dialog_content = "I mean, it's a contest that'll only be fun if there are a lot of contestants.",
  str_homestory_N24diaoyu_90050103_25_dialog_content = "And it's also my job to make sure good Anglers have a chance to shine.",
  str_homestory_N24diaoyu_90050103_26_dialog_content = "But you'll have to prove yourselves to me first.",
  str_homestory_N24diaoyu_90050103_27_dialog_content = "What are you suggesting?",
  str_homestory_N24diaoyu_90050103_28_dialog_content = "Five Knifefish per person.",
  str_homestory_N24diaoyu_90050103_29_dialog_content = "The first one who comes back with five also gets a surprise gift!",
  str_homestory_N24diaoyu_90050103_30_dialog_content = "Got it! Let's go, Vice, Carleen!",
  str_homestory_N24diaoyu_90050104_1_dialog_content = "You sure you have enough?",
  str_homestory_N24diaoyu_90050104_2_dialog_content = "Yes! ({1}/{2})",
  str_homestory_N24diaoyu_90050104_3_dialog_content = "Only a few more to go. Just a moment!",
  str_homestory_N24diaoyu_90050104_4_dialog_content = "Good luck!",
  str_homestory_N24diaoyu_90050104_5_dialog_content = "Well, that's fast.",
  str_homestory_N24diaoyu_90050104_6_dialog_content = "<sprite=emo_dianzan size=60 />Looks like PlayerName really wasn't kidding.",
  str_homestory_N24diaoyu_90050104_7_dialog_content = "Heheh! Of course! I got back here as soon as I caught the fish!",
  str_homestory_N24diaoyu_90050104_8_dialog_content = "They are not back yet?",
  str_homestory_N24diaoyu_90050104_9_dialog_content = "Nope. Well, as promised, you get the first pick of your fishing rod, PlayerName.",
  str_homestory_N24diaoyu_90050104_10_dialog_content = "That's the surprise gift you mentioned?",
  str_homestory_N24diaoyu_90050104_11_dialog_content = "Yeah. We prepared many different fishing rods for our contestants. Only an approved Angler gets to hold one of our certified fishing rods.",
  str_homestory_N24diaoyu_90050104_12_dialog_content = "So what will you have? A Fire, Water, or Grass fishing rod?",
  str_homestory_N24diaoyu_90050104_13_dialog_content = "Um... What's the difference?",
  str_homestory_N24diaoyu_90050104_14_dialog_content = "You'll have to find out for yourself! Maybe it'll give you a special skill or grow with you. Or maybe there's no difference at all!",
  str_homestory_N24diaoyu_90050104_15_dialog_content = "It's just a fishing rod, after all. But once you pick it, it'll become your best buddy.",
  str_homestory_N24diaoyu_90050104_16_dialog_content = "Then I'll pick...",
  str_homestory_N24diaoyu_90050104_17_option_content = "The Grass fishing rod!",
  str_homestory_N24diaoyu_90050104_18_option_content = "The Fire fishing rod!",
  str_homestory_N24diaoyu_90050104_19_option_content = "The Water fishing rod!",
  str_homestory_N24diaoyu_90050104_20_dialog_content = "Wow! It feels good to hold!",
  str_homestory_N24diaoyu_90050104_21_dialog_content = "<sprite=emo_tanqi size=60 />But I don't think it has any of those special abilities...",
  str_homestory_N24diaoyu_90050104_22_dialog_content = "I'm back.",
  str_homestory_N24diaoyu_90050104_23_dialog_content = "You're back, Carleen.",
  str_homestory_N24diaoyu_90050104_24_dialog_content = "Please pick a fishing rod out of the remaining two.",
  str_homestory_N24diaoyu_90050104_25_dialog_content = "Whatever... Any would do.",
  str_homestory_N24diaoyu_90050104_26_dialog_content = "Now that you have your fishing rod, why don't you try it out?",
  str_homestory_N24diaoyu_90050104_27_dialog_content = "Let's begin the first round of the contest while waiting for Vice to get back.",
  str_homestory_N24diaoyu_90050104X_1_dialog_content = "PlayerName, your fishing rod looks powerful.",
  str_homestory_N24diaoyu_90050104X_2_dialog_content = "Are you prepared to have a contest with me first?",
  str_homestory_N24diaoyu_90050104X_3_option_content = "I'm ready.",
  str_homestory_N24diaoyu_90050104X_4_option_content = "Not yet.",
  str_homestory_N24diaoyu_90050105_1_dialog_content = "You're pretty good at this, PlayerName.",
  str_homestory_N24diaoyu_90050105_2_dialog_content = "You sure are a natural at fishing, PlayerName.",
  str_homestory_N24diaoyu_90050105_3_dialog_content = "<sprite=emo_guilian size=60 />Heheh, it's not just that. I had lots of practice in Cloud Gardens!",
  str_homestory_N24diaoyu_90050105_4_dialog_content = "(That, and many people asked me to get all kinds of fish for them.)",
  str_homestory_N24diaoyu_90050105_5_dialog_content = "Huh? You guys are so fast. I only caught enough just now.",
  str_homestory_N24diaoyu_90050105_6_dialog_content = "It's fine, Vice. We're all waiting for you.",
  str_homestory_N24diaoyu_90050105_7_dialog_content = "Here's your fishing rod. You're now an Angler!",
  str_homestory_N24diaoyu_90050105_8_dialog_content = "Then, I'll look forward to seeing you in the contest—",
  str_homestory_N24diaoyu_90050105_9_dialog_content = "For the champion—",
  str_homestory_N24diaoyu_90050105_10_dialog_content = "For the museum—",
  str_homestory_N24diaoyu_90050105_11_dialog_content = "For the Lumamber—",
  str_homestory_N24diaoyu_90050105_12_dialog_content = "<sprite=emo_caitiao size=60 />Good luck!",
  str_homestory_N24diaoyu_90050201_1_dialog_content = "Right. Now that I'm an approved Angler, I shall begin my journey to becoming the champion!",
  str_homestory_N24diaoyu_90050201_2_dialog_content = "First things first!",
  str_homestory_N24diaoyu_90050201_3_dialog_content = "Um... First thing...",
  str_homestory_N24diaoyu_90050201_4_dialog_content = "<sprite=emo_xiaoku size=60 />I... don't think I'm familiar with the rules yet.",
  str_homestory_N24diaoyu_90050201_5_dialog_content = "That's embarrassing. Going after Bethel with questions after that kind of speech...",
  str_homestory_N24diaoyu_90050201_6_dialog_content = "That's not very champion-like.",
  str_homestory_N24diaoyu_90050201_7_dialog_content = "Everyone should know about the rules, so it's the same if I ask someone else! Right!",
  str_homestory_N24diaoyu_90050201_8_dialog_content = "Hmm? Isn't that Lilica over there? She's from Umbraton, and she's a know-it-all.",
  str_homestory_N24diaoyu_90050201_9_dialog_content = "I should go ask her.",
  str_homestory_N24diaoyu_90050202_1_dialog_content = "Lilica.",
  str_homestory_N24diaoyu_90050202_2_dialog_content = "<sprite=emo_laba size=60 />Lilica—",
  str_homestory_N24diaoyu_90050202_3_dialog_content = "Eh?!",
  str_homestory_N24diaoyu_90050202_4_dialog_content = "You scared me...",
  str_homestory_N24diaoyu_90050202_5_dialog_content = "Didn't expect to meet you here, PlayerName.",
  str_homestory_N24diaoyu_90050202_6_dialog_content = "I just came up with an extraordinary idea for a scene!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050202_7_dialog_content = "Sorry to intrude upon your thoughts, then!",
  str_homestory_N24diaoyu_90050202_8_dialog_content = "Oh, it's fine. My inspiration was running dry anyway. I was about to take a break.",
  str_homestory_N24diaoyu_90050202_9_dialog_content = "So, what do you need?",
  str_homestory_N24diaoyu_90050202_10_dialog_content = "Actually, you're quite a know-it-all around here.",
  str_homestory_N24diaoyu_90050202_11_dialog_content = "Oh? That's a nice compliment. What are you buttering me up for?",
  str_homestory_N24diaoyu_90050202_12_dialog_content = "Do you know about a fishing contest called An Extraordinary Catch?",
  str_homestory_N24diaoyu_90050202_13_dialog_content = "Sure. It's what everyone's talking about recently.",
  str_homestory_N24diaoyu_90050202_14_dialog_content = "Right... Maybe I can write a script about fishing.",
  str_homestory_N24diaoyu_90050202_15_dialog_content = "The protagonists are two brothers, and their father is a teacher. The older sibling is a good and honest man and inherited the family business after he graduated.",
  str_homestory_N24diaoyu_90050202_16_dialog_content = "And the younger sibling is a romanticist and adores nature. He learned a special method of fishing.",
  str_homestory_N24diaoyu_90050202_17_dialog_content = "However, he was addicted to gambling and only got out of it with the help of his brother.",
  str_homestory_N24diaoyu_90050202_18_dialog_content = "W-Wait a minute... You could do that later.",
  str_homestory_N24diaoyu_90050202_19_dialog_content = "After you tell me about the rules of the contest, if you know.",
  str_homestory_N24diaoyu_90050202_20_dialog_content = "But the older brother went missing, and the younger brother caught a shark during a fishing trip.",
  str_homestory_N24diaoyu_90050202_21_dialog_content = "He found his brother's body in the shark's belly, and this became a strange murder case.",
  str_homestory_N24diaoyu_90050202_22_dialog_content = "Oh! Right. You're asking me about the rules. Sure, I can help you.",
  str_homestory_N24diaoyu_90050202_23_dialog_content = "Really?",
  str_homestory_N24diaoyu_90050202_24_dialog_content = "But you know how it goes. You need to do something for me.",
  str_homestory_N24diaoyu_90050202_25_dialog_content = "Gather some wood for me. I want to build a set.",
  str_homestory_N24diaoyu_90050202_26_dialog_content = "Right. I'll be right back.",
  str_homestory_N24diaoyu_90050203_1_dialog_content = "Did you find the wood? I'm really trying to come up with a good plot here!",
  str_homestory_N24diaoyu_90050203_2_dialog_content = "Found it! ({1}/{2})",
  str_homestory_N24diaoyu_90050203_3_dialog_content = "Good job!",
  str_homestory_N24diaoyu_90050203_4_dialog_content = "Just a bit more. Go back to thinking for a while longer!",
  str_homestory_N24diaoyu_90050203_5_dialog_content = "Alright, alright. Just hurry up.",
  str_homestory_N24diaoyu_90050203_6_dialog_content = "Good job!",
  str_homestory_N24diaoyu_90050203_7_dialog_content = "That's fast.",
  str_homestory_N24diaoyu_90050203_8_dialog_content = "Of course. I'm a master at running errands now!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050203_9_dialog_content = "You were also quite handy previously when shooting the film. Ever consider doing some work at shooting sites?",
  str_homestory_N24diaoyu_90050203_10_dialog_content = "<sprite=emo_hanshui size=60 />Hahaha... I'll give it some thought. I just hope it'll be safer the next time.",
  str_homestory_N24diaoyu_90050203_11_dialog_content = "Heheh. Since you're a master at this, can you also get me some fish for dinner?",
  str_homestory_N24diaoyu_90050203_12_dialog_content = "Um... You raked in quite a bit with the last movie. Why do you need to catch fish for dinner in Cloud Gardens?",
  str_homestory_N24diaoyu_90050203_13_dialog_content = "It's called being frugal! I'm saving the money for the sequel to Into the Haunted House.",
  str_homestory_N24diaoyu_90050203_14_dialog_content = "Fine. I'll just think of it as practice for the contest. Just wait here for me.",
  str_homestory_N24diaoyu_90050204_1_dialog_content = "Where's my dinner?",
  str_homestory_N24diaoyu_90050204_2_dialog_content = "Wow! The fish look very spirited. ({1}/{2})",
  str_homestory_N24diaoyu_90050204_3_dialog_content = "Just a little more. It's not enough, is it?",
  str_homestory_N24diaoyu_90050204_4_dialog_content = "Oh, it's okay. I'm not hungry yet. You can try to catch some more, PlayerName.",
  str_homestory_N24diaoyu_90050204_5_dialog_content = "<sprite=emo_caitiao size=60 />Whoa! That's a lot. This will be enough for days.",
  str_homestory_N24diaoyu_90050204_6_dialog_content = "Hmm... You're planning to have fish every day for the next few days?",
  str_homestory_N24diaoyu_90050204_7_dialog_content = "I may also ask Cellulo to get some fruit for me.",
  str_homestory_N24diaoyu_90050204_8_dialog_content = "(I better do what Lilica says.)",
  str_homestory_N24diaoyu_90050204_9_dialog_content = "(I don't want to hurt her feelings by saying what I think.)",
  str_homestory_N24diaoyu_90050204_10_dialog_content = "So... What about the rules?",
  str_homestory_N24diaoyu_90050204_11_dialog_content = "Right! Almost forgot.",
  str_homestory_N24diaoyu_90050204_12_dialog_content = "You're not playing me, are you?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050204_13_dialog_content = "Kidding! I'm only kidding!",
  str_homestory_N24diaoyu_90050204_14_dialog_content = "Actually, I don't know the rules myself, but I know someone who does.",
  str_homestory_N24diaoyu_90050204_15_dialog_content = "You'll also need to go through her to become a real Angler.",
  str_homestory_N24diaoyu_90050204_16_dialog_content = "What do you mean by that?",
  str_homestory_N24diaoyu_90050204_17_dialog_content = "Fia. She's the contest's official instructor and specialist.",
  str_homestory_N24diaoyu_90050204_18_dialog_content = "What... Fia? I just turned her request down not long ago...",
  str_homestory_N24diaoyu_90050204_19_dialog_content = "Hmm? Did something happen between you two?",
  str_homestory_N24diaoyu_90050204_20_dialog_content = "She shouldn't be the kind to hold a grudge, right? Just talk to her.",
  str_homestory_N24diaoyu_90050204_21_dialog_content = "Yeah... You're right!",
  str_homestory_N24diaoyu_90050204_22_dialog_content = "Well, thanks, Lilica! I'll see you later!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050205_1_dialog_content = "Hey, Fia—",
  str_homestory_N24diaoyu_90050205_2_dialog_content = "<sprite=emo_emo size=60 />Well, isn't this Mr. Curator of the Museum, PlayerName?",
  str_homestory_N24diaoyu_90050205_3_dialog_content = "I thought you were a busy man.",
  str_homestory_N24diaoyu_90050205_4_dialog_content = "Hmm... You're still upset?",
  str_homestory_N24diaoyu_90050205_5_dialog_content = "(It's time to take the initiative to apologize!)",
  str_homestory_N24diaoyu_90050205_6_dialog_content = "<sprite=emo_tanqi size=60 />I'm so sorry about earlier. It was my bad, and I've learned from my mistake!",
  str_homestory_N24diaoyu_90050205_7_dialog_content = "Humph! So you're not making any excuses. Good.",
  str_homestory_N24diaoyu_90050205_8_dialog_content = "You're here because of the contest, aren't you?",
  str_homestory_N24diaoyu_90050205_9_dialog_content = "That's right. I knew you wouldn't hold a grudge, Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050205_10_dialog_content = "Don't thank me yet. I haven't said I'm gonna help you.",
  str_homestory_N24diaoyu_90050205_11_dialog_content = "If you want to get into the contest, you have to beat me first.",
  str_homestory_N24diaoyu_90050205_12_dialog_content = "Now, PlayerName, show me what you've got!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050205X_1_dialog_content = "Can we start yet? I'm a very busy person.",
  str_homestory_N24diaoyu_90050205X_2_option_content = "Yes!",
  str_homestory_N24diaoyu_90050205X_3_option_content = "I suddenly remembered there was something I needed to do!",
  str_homestory_N24diaoyu_90050206_1_dialog_content = "Um...! Fia, I didn't expect you to be this good.",
  str_homestory_N24diaoyu_90050206_2_dialog_content = "Huh? Not bad. Not bad. I'm impressed, slightly. You passed.",
  str_homestory_N24diaoyu_90050206_3_dialog_content = "Now I feel a bit better after some exercise.",
  str_homestory_N24diaoyu_90050206_4_dialog_content = "I'll forgive you for earlier, then.",
  str_homestory_N24diaoyu_90050206_5_dialog_content = "But, don't you think I gave it my best. I let you off easy.",
  str_homestory_N24diaoyu_90050206_6_dialog_content = "You let me off easy? You're amazing, Fia!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050206_7_dialog_content = "Oh, now you're just being a bootlicker!",
  str_homestory_N24diaoyu_90050206_8_dialog_content = "You better put some time in if you want to become the champion.",
  str_homestory_N24diaoyu_90050206_9_dialog_content = "Now, go forth and beat three <color=#FFB400>Master Anglers</color>!",
  str_homestory_N24diaoyu_90050206_10_dialog_content = "The doorway to the championship will only be opened after you defeat three Master Anglers.",
  str_homestory_N24diaoyu_90050206_11_dialog_content = "I'll look forward to your results.",
  str_homestory_N24diaoyu_90050206_12_dialog_content = "Understood!",
  str_homestory_N24diaoyu_90050301_1_dialog_content = "Hey, PlayerName!",
  str_homestory_N24diaoyu_90050301_2_dialog_content = "Brock? What are you doing here?",
  str_homestory_N24diaoyu_90050301_3_dialog_content = "Same old, same old. Daily training, of course.<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050301_4_dialog_content = "I've been training tirelessly every day to ready myself for the throne of the Rediesel Wrench.",
  str_homestory_N24diaoyu_90050301_5_dialog_content = "Right... I shall take my leave of you then...",
  str_homestory_N24diaoyu_90050301_6_dialog_content = "Wait a minute.",
  str_homestory_N24diaoyu_90050301_7_dialog_content = "Hey, PlayerName, hold it. Don't you feel there's something missing in Cloud Gardens?",
  str_homestory_N24diaoyu_90050301_8_dialog_content = "Hmm? What's missing?",
  str_homestory_N24diaoyu_90050301_9_dialog_content = "If you're proposing something, I'm sure it's useless.<sprite=emo_xiaoku size=60 />",
  str_homestory_N24diaoyu_90050301_10_dialog_content = "<sprite=emo_shengqi size=60 />Hey! PlayerName! How can you say that? Am I not your best bud?",
  str_homestory_N24diaoyu_90050301_11_dialog_content = "I'm being very serious! The least you could do is listen!",
  str_homestory_N24diaoyu_90050301_12_dialog_content = "Fine, fine. Go ahead.",
  str_homestory_N24diaoyu_90050301_13_dialog_content = "Ahem! Don't you think we need some large physical training facilities here?",
  str_homestory_N24diaoyu_90050301_14_dialog_content = "For an athlete like me, it's lonely and boring in Cloud Gardens.",
  str_homestory_N24diaoyu_90050301_15_dialog_content = "Why don't you just find a building and run around it?",
  str_homestory_N24diaoyu_90050301_16_dialog_content = "That's aerobic. What I need is high-intensity resistance training!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050301_17_dialog_content = "<sprite=emo_yihuo size=60 />High-intensity... re-what training?",
  str_homestory_N24diaoyu_90050301_18_dialog_content = "Just get me some ores, and I'll build the training machines for you!",
  str_homestory_N24diaoyu_90050301_19_dialog_content = "Huh? No way. I'm busy right now!",
  str_homestory_N24diaoyu_90050301_20_dialog_content = "Busy doing what? You're busy trying to track down a Master Angler, aren't you?",
  str_homestory_N24diaoyu_90050301_21_dialog_content = "How did you know?",
  str_homestory_N24diaoyu_90050301_22_dialog_content = "All you need to know is: you help me, and I help you.",
  str_homestory_N24diaoyu_90050301_23_dialog_content = "Fine... I'll trust you.",
  str_homestory_N24diaoyu_90050302_1_dialog_content = "You got enough? I can't wait!",
  str_homestory_N24diaoyu_90050302_2_dialog_content = "Good! They're all here. ({1}/{2})",
  str_homestory_N24diaoyu_90050302_3_dialog_content = "Just a bit more. Wait a bit longer.",
  str_homestory_N24diaoyu_90050302_4_dialog_content = "Come on! My blood is boiling right now!",
  str_homestory_N24diaoyu_90050302_5_dialog_content = "Well, I gotta say, you're in pretty good shape, PlayerName.",
  str_homestory_N24diaoyu_90050302_6_dialog_content = "Stop messing with me. Just tell me what I need to know about the contest!",
  str_homestory_N24diaoyu_90050302_7_dialog_content = "Don't worry, I'll tell you. Fleur is a Master Angler.",
  str_homestory_N24diaoyu_90050302_8_dialog_content = "What? Fleur is a Master Angler? I thought the Rediesel Wrench is based in the desert...",
  str_homestory_N24diaoyu_90050302_9_dialog_content = "So what? So they're no good at fishing sandworms and things like that?",
  str_homestory_N24diaoyu_90050302_10_dialog_content = "You better not underestimate him just because he's a member of the Rediesel Wrench.",
  str_homestory_N24diaoyu_90050302_11_dialog_content = "I learned that from experience.",
  str_homestory_N24diaoyu_90050302_12_dialog_content = "Okay. I'll go see Fleur, then.",
  str_homestory_N24diaoyu_90050302_13_dialog_content = "Later!",
  str_homestory_N24diaoyu_90050303_1_dialog_content = "Fleur!",
  str_homestory_N24diaoyu_90050303_2_dialog_content = "Oh, hey, PlayerName.",
  str_homestory_N24diaoyu_90050303_3_dialog_content = "You're here for the tasting event?",
  str_homestory_N24diaoyu_90050303_4_dialog_content = "<sprite=emo_yihuo size=60 />What tasting event?",
  str_homestory_N24diaoyu_90050303_5_dialog_content = "I heard from Brock that you're a Master Angler. I'm here to challenge you!",
  str_homestory_N24diaoyu_90050303_6_dialog_content = "Right. I did sign up for that event, which gives away a free fishing rod, for the sake of gathering food ingredients, and I did get a few fish...",
  str_homestory_N24diaoyu_90050303_7_dialog_content = "Guess that's how I became a Master Angler.",
  str_homestory_N24diaoyu_90050303_8_dialog_content = "Saying it like it was nothing, I take it that you really are a good angler, Fleur.",
  str_homestory_N24diaoyu_90050303_9_dialog_content = "Well, let's not wait around! PlayerName the Dragonwave Angler challenges you!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050303_10_dialog_content = "Now is not the time. Sorry.",
  str_homestory_N24diaoyu_90050303_11_dialog_content = "But why?",
  str_homestory_N24diaoyu_90050303_12_dialog_content = "As I said, I'm preparing the food ingredients for the tasting event.<sprite=emo_rou size=60 />",
  str_homestory_N24diaoyu_90050303_13_dialog_content = "This is a new cooking method that I've just learned.",
  str_homestory_N24diaoyu_90050303_14_dialog_content = "Serving fresh seafood with minimal seasoning to preserve the original taste of the food ingredients.",
  str_homestory_N24diaoyu_90050303_15_dialog_content = "However, I just don't have enough food ingredients. What a headache.",
  str_homestory_N24diaoyu_90050303_16_dialog_content = "I'll help!",
  str_homestory_N24diaoyu_90050303_17_dialog_content = "Really? You would do that for me?",
  str_homestory_N24diaoyu_90050303_18_dialog_content = "If you're willing to help, I'll make sure I get it prepared so we can begin our little competition. How's that, PlayerName?",
  str_homestory_N24diaoyu_90050303_19_dialog_content = "Get me some globefish. You can think of it as a warm-up, PlayerName.",
  str_homestory_N24diaoyu_90050303_20_dialog_content = "Leave it to me.",
  str_homestory_N24diaoyu_90050304_1_dialog_content = "Did you get enough globefish?",
  str_homestory_N24diaoyu_90050304_2_dialog_content = "Yes! ({1}/{2})",
  str_homestory_N24diaoyu_90050304_3_dialog_content = "Just a few more. You'll get them soon!",
  str_homestory_N24diaoyu_90050304_4_dialog_content = "Okay. Thanks a lot.",
  str_homestory_N24diaoyu_90050304_5_dialog_content = "Thank you, PlayerName.",
  str_homestory_N24diaoyu_90050304_6_dialog_content = "These fish sure are fresh and alive.",
  str_homestory_N24diaoyu_90050304_7_dialog_content = "How are you gonna prepare the fish?",
  str_homestory_N24diaoyu_90050304_8_dialog_content = "Well... different fishes require different methods.",
  str_homestory_N24diaoyu_90050304_9_dialog_content = "Some need to be deboned, and the head and internal organs that are not suitable for eating also need to be removed first.",
  str_homestory_N24diaoyu_90050304_10_dialog_content = "Then I can fillet the beautiful meat and infuse it with Lumina to kill the parasites in there.",
  str_homestory_N24diaoyu_90050304_11_dialog_content = "You can use Lumina for that!?<sprite=emo_cangshu size=60 />",
  str_homestory_N24diaoyu_90050304_12_dialog_content = "Yup. It's something I just learned too.",
  str_homestory_N24diaoyu_90050304_13_dialog_content = "As for the globefish you just brought in, I need to carefully remove the internal organs, eyes, and even blood.",
  str_homestory_N24diaoyu_90050304_14_dialog_content = "Actually, now that I think about it, there must be some people in the event who resent raw fish.",
  str_homestory_N24diaoyu_90050304_15_dialog_content = "Eating it raw could also cause indigestion in some people.",
  str_homestory_N24diaoyu_90050304_16_dialog_content = "I wonder if you can get me some fresh water, PlayerName?",
  str_homestory_N24diaoyu_90050304_17_dialog_content = "It'd be perfect if I could prepare some fish soup for everyone.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050304_18_dialog_content = "Got it.",
  str_homestory_N24diaoyu_90050305_1_dialog_content = "You have the water?",
  str_homestory_N24diaoyu_90050305_2_dialog_content = "Yes, it's done! ({1}/{2})",
  str_homestory_N24diaoyu_90050305_3_dialog_content = "Not yet. Give me a minute.",
  str_homestory_N24diaoyu_90050305_4_dialog_content = "Sure. Thank you.",
  str_homestory_N24diaoyu_90050305_5_dialog_content = "Thanks a million. You'll have to wait for me a bit. After the food is prepared, do you want to try it first?",
  str_homestory_N24diaoyu_90050305_6_dialog_content = "Really? I didn't have my—wait, I'm here to challenge you!",
  str_homestory_N24diaoyu_90050305_7_dialog_content = "That may be true, PlayerName. Please choose one to do first, eat or compete?",
  str_homestory_N24diaoyu_90050305_8_option_content = "Eat",
  str_homestory_N24diaoyu_90050305_9_dialog_content = "Great. Please wait here. The food should be ready in two hours.",
  str_homestory_N24diaoyu_90050305_10_dialog_content = "That long? Let's just do the competition first!",
  str_homestory_N24diaoyu_90050305_11_option_content = "Compete",
  str_homestory_N24diaoyu_90050305_12_dialog_content = "I see. If that's what you want, then let's begin!",
  str_homestory_N24diaoyu_90050305X1_1_dialog_content = "Shall we start now? Or do you want to eat something first?",
  str_homestory_N24diaoyu_90050305X1_2_option_content = "Alright!",
  str_homestory_N24diaoyu_90050305X1_3_option_content = "Hang on a second...",
  str_homestory_N24diaoyu_90050306_1_dialog_content = "<sprite=emo_xuanyun size=60 />Phew... Almost lost.",
  str_homestory_N24diaoyu_90050306_2_dialog_content = "Hahaha! PlayerName, you are pretty good!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050306_3_dialog_content = "I admit my defeat. You beat me fair and square.",
  str_homestory_N24diaoyu_90050306_4_dialog_content = "Fair and square, really? Now you are making me suspicious.",
  str_homestory_N24diaoyu_90050306_5_dialog_content = "No way. This is an honorable competition. I was very serious about it.",
  str_homestory_N24diaoyu_90050306_6_dialog_content = "Anyway, you've defeated a Master Angler now.",
  str_homestory_N24diaoyu_90050401_1_dialog_content = "Now that I've rested a bit, I should look for the next Master Angler.",
  str_homestory_N24diaoyu_90050401_2_dialog_content = "Hmm... I should look around and gather some intel first.",
  str_homestory_N24diaoyu_90050401_3_dialog_content = "Hey, PlayerName!",
  str_homestory_N24diaoyu_90050401_4_dialog_content = "Hey, Barton. What is it?",
  str_homestory_N24diaoyu_90050401_5_dialog_content = "I heard that you're an Angler too, right?",
  str_homestory_N24diaoyu_90050401_6_dialog_content = "You even defeated Fleur, a Master Angler. Not bad. Not bad.",
  str_homestory_N24diaoyu_90050401_7_dialog_content = "Thanks for the compliment.",
  str_homestory_N24diaoyu_90050401_8_dialog_content = "Not to sound arrogant, but I do know a thing or two about fishing.",
  str_homestory_N24diaoyu_90050401_9_dialog_content = "If that's so, let's have a little friendly competition.",
  str_homestory_N24diaoyu_90050401_10_dialog_content = "It should really help me out to be taught a lesson or two by you.",
  str_homestory_N24diaoyu_90050401_11_dialog_content = "Oh? You signed up for the contest too?",
  str_homestory_N24diaoyu_90050401_12_dialog_content = "That's right. As the founder of the Illumina Navy, fishing is a required skill.",
  str_homestory_N24diaoyu_90050401_13_dialog_content = "Come, PlayerName. Let's see what you've got.",
  str_homestory_N24diaoyu_90050401_14_dialog_content = "I won't go easy on you!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050401_15_dialog_content = "<sprite=emo_daomei size=60 />Darn it... I didn't expect Barton would be so good at this.",
  str_homestory_N24diaoyu_90050401_16_dialog_content = "Looks like you have a long way to go, weakling.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050401_17_dialog_content = "You lack conviction in your casting and reeling.",
  str_homestory_N24diaoyu_90050401_18_dialog_content = "What's more important is that you are filled with doubt.",
  str_homestory_N24diaoyu_90050401_19_dialog_content = "If you couldn't defeat me, you wouldn't be able to defeat other Master Anglers.",
  str_homestory_N24diaoyu_90050401_20_dialog_content = "If this is just a game to you, you better just give it up now!",
  str_homestory_N24diaoyu_90050401_21_dialog_content = "<sprite=emo_tanqi size=60 />I... How is that possible that I lost?",
  str_homestory_N24diaoyu_90050401_22_dialog_content = "I've even bested Fleur...",
  str_homestory_N24diaoyu_90050401_23_dialog_content = "But I cannot deny that Barton really is a pro at this.",
  str_homestory_N24diaoyu_90050401_24_dialog_content = "I need to be better! But how do I improve?",
  str_homestory_N24diaoyu_90050401_25_dialog_content = "Man...",
  str_homestory_N24diaoyu_90050401_26_dialog_content = "Hey, isn't this my little Caelestite?",
  str_homestory_N24diaoyu_90050401_27_dialog_content = "Oh, Azure...",
  str_homestory_N24diaoyu_90050401_28_dialog_content = "Why the long face? Did someone bully you?",
  str_homestory_N24diaoyu_90050401_29_dialog_content = "I... I lost the fishing competition to Barton.",
  str_homestory_N24diaoyu_90050401_30_dialog_content = "So... you signed up for the contest too?",
  str_homestory_N24diaoyu_90050401_31_dialog_content = "Yeah. But I'm not good enough to win.",
  str_homestory_N24diaoyu_90050401_32_dialog_content = "I got so full of myself just because I bested Fleur.",
  str_homestory_N24diaoyu_90050401_33_dialog_content = "But, in truth, I'm nowhere near a pro...",
  str_homestory_N24diaoyu_90050401_34_dialog_content = "Alright, alright. Have you heard a saying that goes, \"a bad mood scares the fish away\"?",
  str_homestory_N24diaoyu_90050401_35_dialog_content = "Never. You just made it up, didn't you?",
  str_homestory_N24diaoyu_90050401_36_dialog_content = "Hahaha! You've got me, little Caelestite.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050401_37_dialog_content = "Why don't you do me a favor? Go take a stroll, or just go do something. Anything.",
  str_homestory_N24diaoyu_90050401_38_dialog_content = "How about fetching me some water?",
  str_homestory_N24diaoyu_90050401_39_dialog_content = "Water? What do you need water for?",
  str_homestory_N24diaoyu_90050401_40_dialog_content = "Don't ask. Just do me this favor.",
  str_homestory_N24diaoyu_90050402_1_dialog_content = "You got the water?",
  str_homestory_N24diaoyu_90050402_2_dialog_content = "Good. ({1}/{2})",
  str_homestory_N24diaoyu_90050402_3_dialog_content = "Well, you're fast.",
  str_homestory_N24diaoyu_90050402_4_dialog_content = "Not yet...",
  str_homestory_N24diaoyu_90050402_5_dialog_content = "Cheer up. Promise me that you'll go fetch the water first.",
  str_homestory_N24diaoyu_90050402_6_dialog_content = "Now, put the water down. How do you feel now?",
  str_homestory_N24diaoyu_90050402_7_dialog_content = "Hmm... Not as upset as before.",
  str_homestory_N24diaoyu_90050402_8_dialog_content = "Uh-huh. Do you know why Cloud Gardens was chosen as the venue for the contest?",
  str_homestory_N24diaoyu_90050402_9_dialog_content = "Well... Because I don't mind a fishing contest being held here?",
  str_homestory_N24diaoyu_90050402_10_dialog_content = "That's one of the reasons, but not the reason.",
  str_homestory_N24diaoyu_90050402_11_dialog_content = "It's because the fishes here in Cloud Gardens are different from everywhere else's.",
  str_homestory_N24diaoyu_90050402_12_dialog_content = "They can feel nearby emotions. If you're not focused, or if you're not determined, they can sense that and become alert.",
  str_homestory_N24diaoyu_90050402_13_dialog_content = "That's why this place was chosen to hold the contest.",
  str_homestory_N24diaoyu_90050402_14_dialog_content = "And that's also the reason why you lost to Barton.",
  str_homestory_N24diaoyu_90050402_15_dialog_content = "You lack conviction and focus.",
  str_homestory_N24diaoyu_90050402_16_dialog_content = "This contest tests not only your technique, but also your determination and commitment.",
  str_homestory_N24diaoyu_90050402_17_dialog_content = "I-Is that so?",
  str_homestory_N24diaoyu_90050402_18_dialog_content = "Barton also said something similar just now.",
  str_homestory_N24diaoyu_90050402_19_dialog_content = "I want to be better!<sprite=emo_yaling size=60 />",
  str_homestory_N24diaoyu_90050402_20_dialog_content = "You said it so well.",
  str_homestory_N24diaoyu_90050402_21_dialog_content = "Come... little Caelestite.",
  str_homestory_N24diaoyu_90050402_22_dialog_content = "I'll teach you how to hold the rod properly.",
  str_homestory_N24diaoyu_90050402_23_dialog_content = "W-Wait! You're getting too close!",
  str_homestory_N24diaoyu_90050402_24_dialog_content = "You must be patient. This is a very serious lesson.",
  str_homestory_N24diaoyu_90050402_25_dialog_content = "You have a lot to learn to become the champion!",
  str_homestory_N24diaoyu_90050402_26_dialog_content = "Well... I gotta say, Azure did teach me quite a bit about fishing.",
  str_homestory_N24diaoyu_90050402_27_dialog_content = "I shall go challenge Barton again, right now!",
  str_homestory_N24diaoyu_90050403_1_dialog_content = "Oh, you're back, weakling.<sprite=emo_gezitou size=60 />",
  str_homestory_N24diaoyu_90050403_2_dialog_content = "That's a good look. You look like you have what it takes now.",
  str_homestory_N24diaoyu_90050403_3_dialog_content = "That's right. The old me is dead. I am the new me!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050403_4_dialog_content = "Do you want to do it again?",
  str_homestory_N24diaoyu_90050403_5_option_content = "Let's do this!",
  str_homestory_N24diaoyu_90050403_6_option_content = "I'm not ready yet.",
  str_homestory_N24diaoyu_90050404_1_dialog_content = "Ugh! I lost!",
  str_homestory_N24diaoyu_90050404_2_dialog_content = "I didn't expect you'd be able to grow so much in such a short time.",
  str_homestory_N24diaoyu_90050404_3_dialog_content = "<sprite=emo_woshou size=60 />I gotta admit that you are better than me now.",
  str_homestory_N24diaoyu_90050404_4_dialog_content = "Rules are rules... I'll give you the money I...",
  str_homestory_N24diaoyu_90050404_5_dialog_content = "Wait a minute! There aren't any rules like that! This is not like the pit fight of wondrous beasts!",
  str_homestory_N24diaoyu_90050404_6_dialog_content = "Oh... You're right.",
  str_homestory_N24diaoyu_90050404_7_dialog_content = "Then, I'll tell you where you can find the next Master Angler.",
  str_homestory_N24diaoyu_90050405_1_dialog_content = "This should be the place where Barton told me to get to.",
  str_homestory_N24diaoyu_90050405_2_dialog_content = "Hmm? Why are you here, little Caelestite?",
  str_homestory_N24diaoyu_90050405_3_dialog_content = "Did you beat Barton already?",
  str_homestory_N24diaoyu_90050405_4_dialog_content = "Yeah! Thanks to you, I've bested Barton!",
  str_homestory_N24diaoyu_90050405_5_dialog_content = "That's great news.",
  str_homestory_N24diaoyu_90050405_6_dialog_content = "You do realize you owe me one, right?",
  str_homestory_N24diaoyu_90050405_7_dialog_content = "Heheh! I promise I won't forget it.",
  str_homestory_N24diaoyu_90050405_8_dialog_content = "By the way, the one Barton spoke of should be here... but where?",
  str_homestory_N24diaoyu_90050405_9_dialog_content = "You're looking at her.",
  str_homestory_N24diaoyu_90050405_10_dialog_content = "Huh? You mean...",
  str_homestory_N24diaoyu_90050405_11_dialog_content = "That's exactly what I mean.",
  str_homestory_N24diaoyu_90050405_12_dialog_content = "What? I hope your spirit is not so easily dampened.",
  str_homestory_N24diaoyu_90050405_13_dialog_content = "No... I thought about the possibility that it could be you.",
  str_homestory_N24diaoyu_90050405_14_dialog_content = "But no. I'm confident and committed. Let's compete!<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050405_15_dialog_content = "I'm so relieved.",
  str_homestory_N24diaoyu_90050405_16_dialog_content = "Let me see how much you've improved.",
  str_homestory_N24diaoyu_90050405X_1_option_content = "Well, I won't hold anything back, then... Let's go!",
  str_homestory_N24diaoyu_90050405X_2_option_content = "Nope, I still have to practice some more.",
  str_homestory_N24diaoyu_90050406_6_dialog_content = "Well, well, I thought you owed me a favor, yet you really didn't hesitate.",
  str_homestory_N24diaoyu_90050406_7_dialog_content = "Because I know you wouldn't want me to go easy on you, especially in a competition.",
  str_homestory_N24diaoyu_90050406_8_dialog_content = "That's right. They are two different things.",
  str_homestory_N24diaoyu_90050406_9_dialog_content = "But I'm truly impressed by how you were able to beat me. Nicely done.",
  str_homestory_N24diaoyu_90050406_10_dialog_content = "And that you're no longer bothered or affected by other things.",
  str_homestory_N24diaoyu_90050406_11_dialog_content = "<sprite=emo_caitiao size=60 />Congratulations. You've defeated two Master Anglers. You are now a great Angler.",
  str_homestory_N24diaoyu_90050501_1_dialog_content = "Right. I've beaten two Master Anglers.",
  str_homestory_N24diaoyu_90050501_2_dialog_content = "Despite some setbacks, I am still progressing well.",
  str_homestory_N24diaoyu_90050501_3_dialog_content = "Now, all I need is to defeat one final Master Angler to win!",
  str_homestory_N24diaoyu_90050501_4_dialog_content = "I should go gather some intel about the last Master Angler.",
  str_homestory_N24diaoyu_90050501_5_dialog_content = "<sprite=emo_tanqi size=60 />*Sighs*",
  str_homestory_N24diaoyu_90050501_6_dialog_content = "Huh? That voice?",
  str_homestory_N24diaoyu_90050501_7_dialog_content = "Axelia? Why are you here sighing like that?",
  str_homestory_N24diaoyu_90050501_8_dialog_content = "PlayerName...",
  str_homestory_N24diaoyu_90050501_9_dialog_content = "Is that a fishing rod on you? So you're also an...",
  str_homestory_N24diaoyu_90050501_10_dialog_content = "That's right. I am the Dragonwave Angler!<sprite=emo_mojing size=60 />",
  str_homestory_N24diaoyu_90050501_11_dialog_content = "Nice.",
  str_homestory_N24diaoyu_90050501_12_dialog_content = "I'm jealous.",
  str_homestory_N24diaoyu_90050501_13_dialog_content = "Jealous of how you're healthy and able to join a fishing contest, PlayerName.",
  str_homestory_N24diaoyu_90050501_14_dialog_content = "I'm so very jealous.",
  str_homestory_N24diaoyu_90050501_15_dialog_content = "Um... Why don't you just go sign up for it if you want to join as well?",
  str_homestory_N24diaoyu_90050501_16_dialog_content = "I am already an Angler, actually.",
  str_homestory_N24diaoyu_90050501_17_dialog_content = "But I want to join an Angler squad.",
  str_homestory_N24diaoyu_90050501_18_dialog_content = "Sadly, the squad leader turned me down, saying I'm too depressed.",
  str_homestory_N24diaoyu_90050501_19_dialog_content = "I am upset, but it's not like I can do anything about it.<sprite=emo_tanqi size=60 />",
  str_homestory_N24diaoyu_90050501_20_dialog_content = "What!? What kind of excuse is that?",
  str_homestory_N24diaoyu_90050501_21_dialog_content = "There's no chance I'm leaving you like this now that I know about it! Come. I'll speak to that squad leader!",
  str_homestory_N24diaoyu_90050502_1_dialog_content = "We're here.",
  str_homestory_N24diaoyu_90050502_2_dialog_content = "Now let's see who is the one that dared to bully Axelia!",
  str_homestory_N24diaoyu_90050502_3_dialog_content = "Who's causing all the noise and commotion?",
  str_homestory_N24diaoyu_90050502_4_dialog_content = "Eh? What's that familiar voice?",
  str_homestory_N24diaoyu_90050502_5_dialog_content = "W-Wait... Fia!?<sprite=emo_yihuo size=60 />",
  str_homestory_N24diaoyu_90050502_6_dialog_content = "Oh, PlayerName.",
  str_homestory_N24diaoyu_90050502_7_dialog_content = "How goes the contest? Don't be a crybaby just because you lost to other contestants.",
  str_homestory_N24diaoyu_90050502_8_dialog_content = "No way! I've already bested two Master Anglers!",
  str_homestory_N24diaoyu_90050502_9_dialog_content = "Both Fleur and Azure are impressed by my skills!",
  str_homestory_N24diaoyu_90050502_10_dialog_content = "And, I've also bested Barton!<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050502_11_dialog_content = "(Even though Barton put me to shame first.)",
  str_homestory_N24diaoyu_90050502_12_dialog_content = "Wow, I'm really impressed. I didn't think you have it in you, PlayerName.",
  str_homestory_N24diaoyu_90050502_13_dialog_content = "I was gonna tell you more about the fishes here to help you.",
  str_homestory_N24diaoyu_90050502_14_dialog_content = "I really am a good Angler. I don't need that to win... Wait, that's not what I'm here for.",
  str_homestory_N24diaoyu_90050502_15_dialog_content = "Then, why are you here?",
  str_homestory_N24diaoyu_90050502_16_dialog_content = "Fia, did you come up with a squad or something?",
  str_homestory_N24diaoyu_90050502_17_dialog_content = "I sure did! The Full House Squad!",
  str_homestory_N24diaoyu_90050502_18_dialog_content = "Why didn't you let Axelia join?",
  str_homestory_N24diaoyu_90050502_19_dialog_content = "...",
  str_homestory_N24diaoyu_90050502_20_dialog_content = "Well... T-That's because...",
  str_homestory_N24diaoyu_90050502_21_dialog_content = "Her personality really doesn't fit in with our squad.",
  str_homestory_N24diaoyu_90050502_22_dialog_content = "And look at her! The color of her cloth is similar to what I'm wearing.",
  str_homestory_N24diaoyu_90050502_23_dialog_content = "Unique personal color is very important to the members of this squad!",
  str_homestory_N24diaoyu_90050502_24_dialog_content = "But you haven't given her a chance to show her abilities, right?",
  str_homestory_N24diaoyu_90050502_25_dialog_content = "Do you think it's right to judge a book by its cover?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050502_26_dialog_content = "Why are you suddenly getting all worked up like that!?",
  str_homestory_N24diaoyu_90050502_27_dialog_content = "I mean, there are requirements to join the squad. If she really has what it takes, then prove it!",
  str_homestory_N24diaoyu_90050502_28_dialog_content = "Go gather some ores, wood, or fish! Just show me the proof first!",
  str_homestory_N24diaoyu_90050502_29_dialog_content = "Don't worry, Axelia. You go gather the ores and wood. I'll help you with the fish.",
  str_homestory_N24diaoyu_90050502_30_dialog_content = "Thanks, PlayerName.",
  str_homestory_N24diaoyu_90050503_1_dialog_content = "You have everything?",
  str_homestory_N24diaoyu_90050503_2_dialog_content = "Bring them over here! ({1}/{2})",
  str_homestory_N24diaoyu_90050503_3_dialog_content = "Oh? Got them all so quickly?",
  str_homestory_N24diaoyu_90050503_4_dialog_content = "Not yet.",
  str_homestory_N24diaoyu_90050503_5_dialog_content = "You can give up at any time.",
  str_homestory_N24diaoyu_90050503_6_dialog_content = "Fine. I admit I judged you too quickly. You may have what it takes to be on the squad.",
  str_homestory_N24diaoyu_90050503_7_dialog_content = "That's great news, Axelia.",
  str_homestory_N24diaoyu_90050503_8_dialog_content = "Thanks for helping me, PlayerName.",
  str_homestory_N24diaoyu_90050503_9_dialog_content = "<sprite=emo_wuzui size=60 />Wait. Did PlayerName help you gather them?",
  str_homestory_N24diaoyu_90050503_10_dialog_content = "Yeah. So what?",
  str_homestory_N24diaoyu_90050503_11_dialog_content = "<sprite=emo_shengqi size=60 />So what? It's a test for Axelia!",
  str_homestory_N24diaoyu_90050503_12_dialog_content = "How can it count if you helped her!?",
  str_homestory_N24diaoyu_90050503_13_dialog_content = "You didn't even bother when I asked for your help earlier, and now you're a bleeding heart!?",
  str_homestory_N24diaoyu_90050503_14_dialog_content = "You're just infuriating!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050503_15_dialog_content = "W-Wait, Fia! I thought you said you'd forgiven me earlier!",
  str_homestory_N24diaoyu_90050503_16_dialog_content = "I forgave you temporarily! Not put it behind me!",
  str_homestory_N24diaoyu_90050503_17_dialog_content = "Humph! Looks like I need to put you in your place, PlayerName!",
  str_homestory_N24diaoyu_90050503_18_dialog_content = "Let's do it the way we do it between two Anglers!",
  str_homestory_N24diaoyu_90050503_19_dialog_content = "Take out your fishing rod, and don't think I'll go easy on you this time!",
  str_homestory_N24diaoyu_90050503_20_dialog_content = "I'll make you beg and cry!",
  str_homestory_N24diaoyu_90050503X1_1_dialog_content = "You stupid PlayerName! Come here so I can beat you!",
  str_homestory_N24diaoyu_90050503X1_2_option_content = "I'll never admit defeat!",
  str_homestory_N24diaoyu_90050503X1_3_option_content = "I don't want to compete now.",
  str_homestory_N24diaoyu_90050504_1_dialog_content = "<sprite=emo_hanshui size=60 />Huff... huff... Fia really is good.",
  str_homestory_N24diaoyu_90050504_2_dialog_content = "Is this what you really got?",
  str_homestory_N24diaoyu_90050504_3_dialog_content = "Thankfully I managed to win, barely. Can you calm down now?",
  str_homestory_N24diaoyu_90050504_4_dialog_content = "<sprite=emo_xinsui size=60 />I... I can't believe it.",
  str_homestory_N24diaoyu_90050504_5_dialog_content = "But honor is everything to an Angler. I'll construe what happened earlier as an apology.",
  str_homestory_N24diaoyu_90050504_6_dialog_content = "Axelia, I officially welcome you as the second member of the squad.",
  str_homestory_N24diaoyu_90050504_7_dialog_content = "Thanks. I'll do my best.",
  str_homestory_N24diaoyu_90050504_8_dialog_content = "(What? Only two people on the squad? Why did she want to join this kind of squad, to begin with?)",
  str_homestory_N24diaoyu_90050504_9_dialog_content = "Now that's what I call a good ending. I should be on my way to finding the next Master Angler.",
  str_homestory_N24diaoyu_90050504_10_dialog_content = "Huh? What next Master Angler?",
  str_homestory_N24diaoyu_90050504_11_dialog_content = "You've bested Fleur and Azure. I am the only one left.",
  str_homestory_N24diaoyu_90050504_12_dialog_content = "What? You're a Master Angler? I thought you were the instructor.",
  str_homestory_N24diaoyu_90050504_13_dialog_content = "Who says an instructor can't be a Master Angler?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050504_14_dialog_content = "Beating me without even knowing that? You really are infuriating, you know.",
  str_homestory_N24diaoyu_90050504_15_dialog_content = "Come! Let's go a few more rounds!",
  str_homestory_N24diaoyu_90050601_1_dialog_content = "My hands are so sore. <sprite=emo_xuanyun size=60 />Dragged into fishing by Fia for over ten hours straight...",
  str_homestory_N24diaoyu_90050601_2_dialog_content = "But I've bested three Master Anglers! PlayerName the Dragonwave Angler triumphs again!",
  str_homestory_N24diaoyu_90050601_3_dialog_content = "Hahaha! Now I should be able to get the prize fishing rod, sell it, and get the money to build a museum!",
  str_homestory_N24diaoyu_90050601_4_dialog_content = "I've been competing with other people for such a long time. I almost forgot the pleasure of fishing leisurely by myself.",
  str_homestory_N24diaoyu_90050601_5_dialog_content = "Let me just do that then, just to relax.",
  str_homestory_N24diaoyu_90050601_6_dialog_content = "<sprite=emo_wuzui size=60 />Hmm!? This strength!",
  str_homestory_N24diaoyu_90050601_7_dialog_content = "An incredible fish just bit the bait!",
  str_homestory_N24diaoyu_90050601_8_dialog_content = "Heh!!",
  str_homestory_N24diaoyu_90050601_9_dialog_content = "<sprite=emo_baimao size=60 />Hmm... Meow.",
  str_homestory_N24diaoyu_90050601_10_dialog_content = "Wh-What the...",
  str_homestory_N24diaoyu_90050601_11_dialog_content = "Philyshy!? How!?",
  str_homestory_N24diaoyu_90050601_12_dialog_content = "Or is this a kind of fish that resembles Philyshy?",
  str_homestory_N24diaoyu_90050601_13_dialog_content = "O-Ouch! It hurts, PlayerName! It's me, Philyshy! Meow!<sprite=emo_baimao size=60 />",
  str_homestory_N24diaoyu_90050601_14_dialog_content = "But... Why would you get caught by me like a fish?",
  str_homestory_N24diaoyu_90050601_15_dialog_content = "Does it matter right now? Hurry, meow! Deliver this document to Officer Vivian for me!",
  str_homestory_N24diaoyu_90050602_1_dialog_content = "Officer Vivian!",
  str_homestory_N24diaoyu_90050602_2_dialog_content = "PlayerName? Why are you in such a hurry?",
  str_homestory_N24diaoyu_90050602_3_dialog_content = "T-This! Philyshy asked me to deliver this to you ASAP.",
  str_homestory_N24diaoyu_90050602_4_dialog_content = "Huh? Philyshy, you say?",
  str_homestory_N24diaoyu_90050602_5_dialog_content = "Let me see... Hmm, this should have been on my desk by yesterday.",
  str_homestory_N24diaoyu_90050602_6_dialog_content = "<sprite=emo_shengqi size=60 />Philyshy... Sometimes I really wonder what she has been doing.",
  str_homestory_N24diaoyu_90050602_7_dialog_content = "Um... There's something that I don't know if I should say or not.",
  str_homestory_N24diaoyu_90050602_8_dialog_content = "I ran into her when I was fishing.",
  str_homestory_N24diaoyu_90050602_9_dialog_content = "She's slacking off and fishing!?",
  str_homestory_N24diaoyu_90050602_10_dialog_content = "No, no. How should I put it? Not that she was fishing.",
  str_homestory_N24diaoyu_90050602_11_dialog_content = "I fished her out of the water...",
  str_homestory_N24diaoyu_90050602_12_dialog_content = "...",
  str_homestory_N24diaoyu_90050602_13_dialog_content = "No matter. PlayerName, would you please kindly go back to Philyshy and tell her to get over here?",
  str_homestory_N24diaoyu_90050603_1_dialog_content = "Philyshy, I'm back.",
  str_homestory_N24diaoyu_90050603_2_dialog_content = "You've delivered the document to Officer Vivian? Thanks! Meow!",
  str_homestory_N24diaoyu_90050603_3_dialog_content = "But I still don't get why you were in the water and ended up on the other end of my fishing rod.",
  str_homestory_N24diaoyu_90050603_4_dialog_content = "Well... I was probably trying to catch fish, slacking off... or daydreaming.",
  str_homestory_N24diaoyu_90050603_5_dialog_content = "N-Not that it matters, meow.",
  str_homestory_N24diaoyu_90050603_6_dialog_content = "I heard that you have bested three Master Anglers, PlayerName.",
  str_homestory_N24diaoyu_90050603_7_dialog_content = "You heard that already?",
  str_homestory_N24diaoyu_90050603_8_dialog_content = "Come on, I am an intelligence officer, meow.<sprite=emo_emo size=60 />",
  str_homestory_N24diaoyu_90050603_9_dialog_content = "That's right. I've defeated three Master Anglers, so I am the champion!",
  str_homestory_N24diaoyu_90050603_10_dialog_content = "<sprite=emo_yihuo size=60 />Huh? But you haven't bested the champion yet.",
  str_homestory_N24diaoyu_90050603_11_dialog_content = "What? I thought I'd automatically win the event after defeating the three Master Anglers.",
  str_homestory_N24diaoyu_90050603_12_dialog_content = "Of course not, meow!",
  str_homestory_N24diaoyu_90050603_13_dialog_content = "You have to defeat the previous champion!",
  str_homestory_N24diaoyu_90050603_14_dialog_content = "Um... No one bothered to tell me that.",
  str_homestory_N24diaoyu_90050603_15_dialog_content = "Geez.",
  str_homestory_N24diaoyu_90050603_16_dialog_content = "Well, to thank you for helping me out, I'll tell you where you can find the champion.",
  str_homestory_N24diaoyu_90050603_17_dialog_content = "Thanks!",
  str_homestory_N24diaoyu_90050603_18_dialog_content = "By the way, Officer Vivian is looking for you.",
  str_homestory_N24diaoyu_90050603_19_dialog_content = "*Sobs* I know, meow... I still can't avoid her, can I?",
  str_homestory_N24diaoyu_90050604_1_dialog_content = "Huh...? Beretta? You are the current champion?",
  str_homestory_N24diaoyu_90050604_2_dialog_content = "Are you talking about the fishing contest?",
  str_homestory_N24diaoyu_90050604_3_dialog_content = "I do remember doing it, sure...",
  str_homestory_N24diaoyu_90050604_4_dialog_content = "Fishing is fun, and I think I bested a few hundred other Anglers without me really knowing.",
  str_homestory_N24diaoyu_90050604_5_dialog_content = "And then I somehow became the champion, not that I care for a title like that.<sprite=emo_qingsong size=60 />",
  str_homestory_N24diaoyu_90050604_5X1_dialog_content = "So, are you here to challenge me?",
  str_homestory_N24diaoyu_90050604_6_dialog_content = "Um... Saying it like it was nothing, the best is always like that, I guess.",
  str_homestory_N24diaoyu_90050604_7_option_content = "Let's see who's better between us!",
  str_homestory_N24diaoyu_90050604_8_option_content = "I need to make more preparations.",
  str_homestory_N24diaoyu_90050605_1_dialog_content = "<sprite=emo_daomei size=60 />Huh...! How is that possible?",
  str_homestory_N24diaoyu_90050605_2_dialog_content = "You're quite good, PlayerName. I guess I have to take you more seriously.",
  str_homestory_N24diaoyu_90050605_3_dialog_content = "There's no competition at all. The fish just go to Beretta like she's a fish magnet or something.",
  str_homestory_N24diaoyu_90050605_4_dialog_content = "There's no way that I can win.",
  str_homestory_N24diaoyu_90050605_5_dialog_content = "Is this the end of my winning streak...?<sprite=emo_xinsui size=60 />",
  str_homestory_N24diaoyu_90050605_6_dialog_content = "PlayerName, you're not giving up already, are you?",
  str_homestory_N24diaoyu_90050605_7_dialog_content = "Did you forget our promise?",
  str_homestory_N24diaoyu_90050605_8_dialog_content = "Vice! Carleen!",
  str_homestory_N24diaoyu_90050605_9_dialog_content = "PlayerName, keep at it! I'll prepare a seafood feast for you if you win!",
  str_homestory_N24diaoyu_90050605_10_dialog_content = "Hey, looking defeated is not a good look for my little Caelestite. Suck it up!",
  str_homestory_N24diaoyu_90050605_11_dialog_content = "Come on! You've bested me, PlayerName. There's no way you're gonna lose to her!",
  str_homestory_N24diaoyu_90050605_12_dialog_content = "<sprite=emo_daku size=60 />Fleur... Azure... and Fia... You're all here.",
  str_homestory_N24diaoyu_90050605_13_dialog_content = "We're not gonna forgive you if you just give up like that, PlayerName!",
  str_homestory_N24diaoyu_90050605_14_dialog_content = "That's it! I'm taking you to the gym with me, PlayerName. I just made a few dumbbells!",
  str_homestory_N24diaoyu_90050605_15_dialog_content = "Barton, you too...",
  str_homestory_N24diaoyu_90050605_16_dialog_content = "Thanks for being here for me, everyone.<sprite=emo_woshou size=60 />",
  str_homestory_N24diaoyu_90050605_17_dialog_content = "Why are you making me look like the final villain boss...?",
  str_homestory_N24diaoyu_90050605_18_dialog_content = "Hey! You're not ignoring me, are you?<sprite=emo_shengqi size=60 />",
  str_homestory_N24diaoyu_90050605_19_dialog_content = "Thank you all... for cheering me on!",
  str_homestory_N24diaoyu_90050605_20_dialog_content = "Now, let me show you the first, and last, ultimate skill of the Dragonwave Angler!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050605X_1_dialog_content = "Do you want to challenge me again? I don't really mind.",
  str_homestory_N24diaoyu_90050605X_2_option_content = "For our companions!",
  str_homestory_N24diaoyu_90050605X_3_option_content = "Just a little longer!",
  str_homestory_N24diaoyu_90050606_1_dialog_content = "Oh... So this is what it's like to lose...",
  str_homestory_N24diaoyu_90050606_2_dialog_content = "I won... I've finally won!",
  str_homestory_N24diaoyu_90050606_3_dialog_content = "Congratulations, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N24diaoyu_90050606_4_dialog_content = "Awesome, PlayerName!",
  str_homestory_N24diaoyu_90050606_5_dialog_content = "I'm touched.<sprite=emo_daku size=60 />",
  str_homestory_N24diaoyu_90050606_6_dialog_content = "You really gave it all you got!",
  str_homestory_N24diaoyu_90050606_7_dialog_content = "How you've really grown, my little Caelestite.<sprite=emo_aixin size=60 />",
  str_homestory_N24diaoyu_90050606_8_dialog_content = "That's more like it!",
  str_homestory_N24diaoyu_90050606_9_dialog_content = "<sprite=emo_sikao size=60 />Are you still ignoring me!?",
  str_homestory_N24diaoyu_90050606_10_dialog_content = "Thank you... Thank you, everyone.",
  str_homestory_N24diaoyu_90050606_11_dialog_content = "Nicely done... So is PlayerName the new champion now?",
  str_homestory_N24diaoyu_90050606_12_dialog_content = "I just happen to bring the host of the event with me. We can give out the rewards now, right?",
  str_homestory_N24diaoyu_90050606_13_dialog_content = "Well... About that...",
  str_homestory_N24diaoyu_90050606_14_dialog_content = "Jomu? You're the one who suggested this to the publisher?",
  str_homestory_N24diaoyu_90050606_15_dialog_content = "I'm impressed. I didn't think you would do anything for free.",
  str_homestory_N24diaoyu_90050606_16_dialog_content = "By the way, where's my prize? That super amazing fishing rod?",
  str_homestory_N24diaoyu_90050606_17_dialog_content = "Yeah, I was getting to that...",
  str_homestory_N24diaoyu_90050606_18_dialog_content = "You know, the price of Lumamber skyrocketed...",
  str_homestory_N24diaoyu_90050606_19_dialog_content = "So I had to switch out the gems on the fishing rod for the leftover ores from Brock.",
  str_homestory_N24diaoyu_90050606_20_dialog_content = "But it's what it stands for that matters, right? I mean, it's a symbol of your mastery!<sprite=emo_dianzan size=60 />",
  str_homestory_N24diaoyu_90050606_21_dialog_content = "Give...",
  str_homestory_N24diaoyu_90050606_22_dialog_content = "Give me my pure gold Lumamber fishing rod!!!<sprite=emo_nuhuo size=60 />",
  str_homestory_N24diaoyu_90050901_1_dialog_content = "Have a competition with Carleen.",
  str_homestory_N24diaoyu_90050902_1_dialog_content = "Fantastic.",
  str_homestory_N24diaoyu_90050903_1_dialog_content = "She's the captain...",
  str_homestory_N24diaoyu_90050904_1_dialog_content = "She looks very angry.",
  str_homestory_N24diaoyu_90050905_1_dialog_content = "Let's listen to what she has to say first.",
  str_homestory_N24diaoyu_90050906_1_dialog_content = "I have no time to explain, meow. Take this intel to Officer Vivian for me first!",
  str_homestory_N24diaoyu_90050907_1_dialog_content = "Please help me call Philyshy over here.",
  str_homestory_N24diaoyu_90050908_1_dialog_content = "As expected of PlayerName! You're simply amazing!",
  str_homestory_N24diaoyu_90050909_1_dialog_content = "No one is as skilled as you, PlayerName.",
  str_homestory_N24diaoyu_90050910_1_dialog_content = "Brilliant!",
  str_homestory_N24diaoyu_90050911_1_dialog_content = "I was right about you, little Caelestite.",
  str_homestory_N24diaoyu_90050912_1_dialog_content = "I don't want to admit it, but PlayerName really is very strong!",
  str_homestory_N24diaoyu_90050913_1_dialog_content = "Whoa! What a satisfying competition!",
  str_homestory_N24diaoyu_90050914_1_dialog_content = "Let's go if you're finished. Let's exercise together!",
  str_homestory_N24diaoyu_90050915_1_dialog_content = "Carleen!",
  str_homestory_N24diaoyu_90050915_2_dialog_content = "Huh? What is it, PlayerName?",
  str_homestory_N24diaoyu_90050915_3_dialog_content = "You keep staring at me like you have something to say.",
  str_homestory_N24diaoyu_90050915_4_dialog_content = "Yeah, I do, actually, but I feel kind of...",
  str_homestory_N24diaoyu_90050915_5_dialog_content = "Feel free to say whatever's on your mind.",
  str_homestory_N24diaoyu_90050915_6_dialog_content = "Okay, then...",
  str_homestory_N24diaoyu_90050915_7_dialog_content = "Yes.",
  str_homestory_N24diaoyu_90050915_8_dialog_content = "Well...",
  str_homestory_N24diaoyu_90050915_9_dialog_content = "What?",
  str_homestory_N24diaoyu_90050915_10_dialog_content = "Have you been practicing fishing in secret, Carleen?",
  str_homestory_N24diaoyu_90050915_11_dialog_content = "...You got me.",
  str_homestory_N24diaoyu_90050915_12_dialog_content = "I have a lot of witnesses.",
  str_homestory_N24diaoyu_90050915_13_dialog_content = "Yes. Since our last round, I've been honing my skills.",
  str_homestory_N24diaoyu_90050915_14_dialog_content = "After studying you, PlayerName, and all of the Master Anglers, I feel like I've learned a lot.",
  str_homestory_N24diaoyu_90050915_15_dialog_content = "I would even say I'm now good enough to be at the level of when you beat Beretta.",
  str_homestory_N24diaoyu_90050915_16_dialog_content = "Really?",
  str_homestory_N24diaoyu_90050915_17_dialog_content = "So, want to try me?",
  str_homestory_N24diaoyu_90050915_18_dialog_content = "Sure. You were my first opponent and an invaluable partner in my quest to be the champion!",
  str_homestory_N24diaoyu_90050915_19_dialog_content = "I'm glad you think that. Let's go to the river, then.",
  str_homestory_N24diaoyu_90050916_1_dialog_content = "Should we begin?",
  str_homestory_N24diaoyu_90050916_2_option_content = "Yeah, I can't wait!",
  str_homestory_N24diaoyu_90050916_3_option_content = "Hang on a second...",
  str_homestory_N24diaoyu_90050917_1_dialog_content = "You sure are good, PlayerName... I concede.",
  str_homestory_N24diaoyu_90050917_2_dialog_content = "You've improved a lot, Carleen. I feel like if I slipped even once, you would beat me.",
  str_homestory_N24diaoyu_90050917_3_dialog_content = "Hmm...",
  str_homestory_N24diaoyu_90050917_4_dialog_content = "Skip the compliments.",
  str_homestory_N24diaoyu_90050917_5_dialog_content = "This is the blue-ringed octopus I caught in practice. You can have it.",
  str_homestory_N24diaoyu_90050917_6_dialog_content = "You sure? It's rare, you know.",
  str_homestory_N24diaoyu_90050917_7_dialog_content = "I'm sure. Next time I catch another one is when I'll beat you, PlayerName.",
  str_homestory_N24diaoyu_90050917_8_dialog_content = "I'll keep practicing too, and be even better next time!",
  str_homestory_N24diaoyu_90050917_9_dialog_content = "We'll go another round again sometime.",
  str_homestory_N24diaoyu_90050917_10_dialog_content = "You got it!",
  str_homestory_N24diaoyu_90050918_1_dialog_content = "I've improved my skills lately. Let's try again.",
  str_homestory_N24diaoyu_90050918_2_option_content = "Let's go!",
  str_homestory_N24diaoyu_90050918_3_option_content = "I just remembered I have something to do.",
  str_homestory_N24diaoyu_90050919_1_dialog_content = "Okay, I'll wait for you here."
}
return config
